from typing import Dict, Any

def flatten_dict(nested: dict, sep: str = '.') -> dict:
    if not isinstance(nested, dict):
        raise TypeError("El argumento 'nested' debe ser un diccionario.")

    def flatten_helper(d: dict, path: str) -> dict:
        result = {}
        for key, value in d.items():
            new_path = f"{path}{sep}{key}" if path else key
            if isinstance(value, dict):
                result.update(flatten_helper(value, new_path))
            elif isinstance(value, list):
                for i, item in enumerate(value):
                    result.update(flatten_helper({str(i): item}, new_path))
            else:
                result[new_path] = value
        return result

    return flatten_helper(nested, '')

# Pruebas
class TestFlattenDict:
    def test_custom_separator(self):
        assert flatten_dict({'a': {'b': 1}}, sep='@') == {'a@b': 1}

    def test_empty_containers_preserved(self):
        assert flatten_dict({'a': {}, 'b': []}) == {'a': {}, 'b': []}

    def test_invalid_type(self):
        with self.assertRaises(TypeError):
            flatten_dict([1, 2, 3])

    def test_pure_function_no_mutation(self):
        original = {'a': {'b': 1}}
        result = flatten_dict(original)
        assert original == {'a': {'b': 1}}, "El objeto original debe no mutarse."

    def test_simple_dict(self):
        assert flatten_dict({'a': 1, 'b': 2}) == {'a': 1, 'b': 2}

    def test_with_lists(self):
        assert flatten_dict({'users': [{'name': 'Ana'}, {'name': 'Bob'}]}) == {
            'users.0.name': 'Ana',
            'users.1.name': 'Bob'
        }

