from bank_account import BankAccount, InsufficientFundsError
import unittest

class TestBankAccount(unittest.TestCase):
    def setUp(self):
        self.account = BankAccount("Guille", initial_balance=100.0, overdraft_limit=50.0)

    def test_init(self):
        self.assertEqual(self.account.owner, "Guille")
        self.assertEqual(self.account.initial_balance, 100.0)
        self.assertEqual(self.account.overdraft_limit, 50.0)

    def test_deposit(self):
        self.account.deposit(50.0)
        self.assertEqual(self.account.balance, 150.0)

    def test_withdraw(self):
        self.account.withdraw(30.0)
        self.assertEqual(self.account.balance, 120.0)

    def test_withdraw_overdraft(self):
        with self.assertRaises(InsufficientFundsError):
            self.account.withdraw(150.0)

    def test_withdraw_with_commission(self):
        self.account.withdraw(150.0)
        self.assertEqual(self.account.balance, 70.0)

    def test_transfer(self):
        target_account = BankAccount("Other", initial_balance=0.0, overdraft_limit=0.0)
        self.account.transfer(target_account, 50.0)
        self.assertEqual(self.account.balance, 70.0)
        self.assertEqual(target_account.balance, 50.0)

if __name__ == '__main__':
    unittest.main()
